    out=[r[:] for r in grid]
    # Sequence is represented on bottom row, terminated by zeros. Markers elsewhere
    # trigger placing a cyclic continuation beginning at marker's color.
    seq=[]
    for x in range(w):
        if grid[h-1][x]: seq.append(grid[h-1][x])
    for y in range(h-1):
        for x in range(w):
            c=grid[y][x]
            if c:
                if c in seq:
                    i=seq.index(c)
                    for k,v in enumerate(seq[i:]):
                        if x+k<w: out[y][x+k]=v
    return out
