def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    # Seed motifs are the contiguous nonzero runs on the top and bottom edges.
    motifs=[]
    for y in (0,h-1):
        x=0
        while x<w:
            if grid[y][x]==0:
                x+=1; continue
            run=[]
            while x<w and grid[y][x]!=0:
                run.append(grid[y][x]); x+=1
            motifs.append(run)
    for y in range(1,h-1):
        for x,c in enumerate(grid[y]):
            if not c: continue
            for motif in motifs:
                if c in motif:
                    start=x-motif.index(c)
                    for j,v in enumerate(motif):
                        xx=start+j
                        if 0<=xx<w: out[y][xx]=v
                    break
    return out
